Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

double absolute(double value) {
    return (value < 0) ? -value : value;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;
    int best_a = 0, best_b = 1;
    double min_diff = 1e15;
    double ratio = static_cast<double>(x) / y;

    for (int j = 1; j <= n; ++j) {
        int left = 0, right = 1000000000;
        while (right - left > 10) {
            int m1 = left + (right - left) / 3;
            int m2 = right - (right - left) / 3;
            double diff1 = absolute(ratio - static_cast<double>(m1) / j);
            double diff2 = absolute(ratio - static_cast<double>(m2) / j);
            if (diff1 > diff2)
                left = m1;
            else
                right = m2;
        }
        for (int i = left; i <= right + 3; ++i) {
            double current_diff = absolute(ratio - static_cast<double>(i) / j);
            if (current_diff < min_diff - 1e-15) {
                min_diff = current_diff;
                best_a = i;
                best_b = j;
            }
        }
    }
    cout << best_a << '/' << best_b;
    return 0;
}
</original_code>
